let cddb_str = cddb_id.to_string();
assert_eq!(Cddb::try_from(cddb_str.as_str()), Ok(cddb_id));
assert_eq!(cddb_str.parse::<Cddb>(), Ok(cddb_id));
```

## Errors

This will return an error if decoding fails.

