This argument is [required] only if the specified `arg` is present at runtime and its value
equals `val`.

# Examples

```rust
# use clap_builder as clap;
# use clap::Arg;
Arg::new("config")
    .required_if_eq("other_arg", "value")
# ;
```

```rust
# use clap_builder as clap;
# use clap::{Command, Arg, error::ErrorKind, ArgAction};
let res = Command::new("prog")
    .arg(Arg::new("cfg")
        .action(ArgAction::Set)
        .required_if_eq("other", "special")
        .long("config"))
    .arg(Arg::new("other")
        .long("other")
        .action(ArgAction::Set))
    .try_get_matches_from(vec![
        "prog", "--other", "not-special"
    ]);

assert!(res.is_ok()); // We didn't use --other=special, so "cfg" wasn't required

let res = Command::new("prog")
    .arg(Arg::new("cfg")
        .action(ArgAction::Set)
        .required_if_eq("other", "special")
        .long("config"))
    .arg(Arg::new("other")
        .long("other")
        .action(ArgAction::Set))
    .try_get_matches_from(vec![
        "prog", "--other", "special"
    ]);

// We did use --other=special so "cfg" had become required but was missing.
assert!(res.is_err());
assert_eq!(res.unwrap_err().kind(), ErrorKind::MissingRequiredArgument);

let res = Command::new("prog")
    .arg(Arg::new("cfg")
        .action(ArgAction::Set)
        .required_if_eq("other", "special")
        .long("config"))
    .arg(Arg::new("other")
        .long("other")
        .action(ArgAction::Set))
    .try_get_matches_from(vec![
        "prog", "--other", "SPECIAL"
    ]);

// By default, the comparison is case-sensitive, so "cfg" wasn't required
assert!(res.is_ok());

let res = Command::new("prog")
    .arg(Arg::new("cfg")
        .action(ArgAction::Set)
        .required_if_eq("other", "special")
        .long("config"))
    .arg(Arg::new("other")
        .long("other")
        .ignore_case(true)
        .action(ArgAction::Set))
    .try_get_matches_from(vec![
        "prog", "--other", "SPECIAL"
    ]);

// However, case-insensitive comparisons can be enabled.  This typically occurs when using Arg::possible_values().
assert!(res.is_err());
assert_eq!(res.unwrap_err().kind(), ErrorKind::MissingRequiredArgument);
```
