    NiceFloat::with_separator(
        1234.5678_f64,
        NiceSeparator::Period,
        NiceSeparator::Comma,
    ).as_str(),
    "1.234,56780000",
);

// The punctuation is also honored for "special" values:
assert_eq!(
    NiceFloat::with_separator(
        0_f64,
        NiceSeparator::Comma,
        NiceSeparator::Space,
    ).as_str(),
    "0 00000000",
);
assert_eq!(
    NiceFloat::with_separator(
        f64::MAX,
        NiceSeparator::Underscore,
        NiceSeparator::Period,
    ).as_str(),
    "> 18_446_744_073_709_551_615",
);
