# (ASCII) Bytes to Unsigned.

Parse a `usize` from an ASCII byte slice.

## Examples

```
use dactyl::traits::BytesToUnsigned;

assert_eq!(
    usize::btou(b"0"),
    Some(usize::MIN),
);
assert_eq!(
    usize::btou(b"18446744073709551615"),
    Some(usize::MAX),
);

// Leading zeroes are fine.
assert_eq!(
    usize::btou(b"00000123"),
    Some(123),
);

// These are all bad.
assert!(usize::btou(&[]).is_none()); // Empty.
assert!(usize::btou(b"+13").is_none()); // Plus.
assert!(usize::btou(b" 2223231  ").is_none()); // Whitespace.
assert!(usize::btou(b"nope").is_none()); // Not a number.
assert!(usize::btou(
    b"4402823669209384634633746074317682114550").is_none()
); // Too big.
```

