```
# futures::executor::block_on(async {
use futures::future::FutureExt;
use futures::stream::StreamExt;

let future = async { 17 };
let stream = future.into_stream();
let collected: Vec<_> = stream.collect().await;
assert_eq!(collected, vec![17]);
