use heapless::FnvIndexSet;

let mut a: FnvIndexSet<_, 16> = [1, 2, 3].iter().cloned().collect();
let mut b: FnvIndexSet<_, 16> = [4, 2, 3, 4].iter().cloned().collect();

// Print 1, 4 in that order.
for x in a.symmetric_difference(&b) {
    println!("{}", x);
