let mut headers = [httparse::EMPTY_HEADER; 16];
let mut req = httparse::Request::new(&mut headers);
let res = req.parse(buf).unwrap();
if res.is_partial() {
    match req.path {
        Some(ref path) => {
            // check router for path.
            // /404 doesn't exist? we could stop parsing
        },
        None => {
            // must read more and parse again
        }
    }
}
```

Sets whether white space before the first header is allowed

This is not allowed by spec but some browsers ignore it. So this an option for
compatibility.
See https://github.com/curl/curl/issues/11605 for reference
# Example

```rust
let buf = b"HTTP/1.1 200 OK\r\n Space-Before-Header: hello there\r\n\r\n";
let mut headers = [httparse::EMPTY_HEADER; 1];
let mut response = httparse::Response::new(&mut headers[..]);
let result = httparse::ParserConfig::default()
    .allow_space_before_first_header_name(true)
    .parse_response(&mut response, buf);

assert_eq!(result, Ok(httparse::Status::Complete(buf.len())));
assert_eq!(response.version.unwrap(), 1);
assert_eq!(response.code.unwrap(), 200);
assert_eq!(response.reason.unwrap(), "OK");
assert_eq!(response.headers.len(), 1);
assert_eq!(response.headers[0].name, "Space-Before-Header");
assert_eq!(response.headers[0].value, &b"hello there"[..]);
```

Sets whether obsolete multiline headers should be allowed.

This is an obsolete part of HTTP/1. Use at your own risk. If you are
building an HTTP library, the newlines (`\r` and `\n`) should be
replaced by spaces before handing the header value to the user.

# Example

```rust
let buf = b"HTTP/1.1 200 OK\r\nFolded-Header: hello\r\n there \r\n\r\n";
let mut headers = [httparse::EMPTY_HEADER; 16];
let mut response = httparse::Response::new(&mut headers);

let res = httparse::ParserConfig::default()
    .allow_obsolete_multiline_headers_in_responses(true)
    .parse_response(&mut response, buf);

assert_eq!(res, Ok(httparse::Status::Complete(buf.len())));

assert_eq!(response.headers.len(), 1);
assert_eq!(response.headers[0].name, "Folded-Header");
assert_eq!(response.headers[0].value, b"hello\r\n there");
```

Parse a buffer of bytes as headers.

The return value, if complete and successful, includes the index of the
buffer that parsing stopped at, and a sliced reference to the parsed
headers. The length of the slice will be equal to the number of properly
parsed headers.

# Example

```
let buf = b"Host: foo.bar\nAccept: */*\n\nblah blah";
let mut headers = [httparse::EMPTY_HEADER; 4];
assert_eq!(httparse::parse_headers(buf, &mut headers),
           Ok(httparse::Status::Complete((27, &[
               httparse::Header { name: "Host", value: b"foo.bar" },
               httparse::Header { name: "Accept", value: b"*/*" }
           ][..]))));
```

Takes a `&Array<Array<T, N>, >>`, and flattens it to a `&[T]`.

# Panics

This panics if the length of the resulting slice would overflow a `usize`.

This is only possible when flattening a slice of arrays of zero-sized
types, and thus tends to be irrelevant in practice. If
`size_of::<T>() > 0`, this will never panic.

# Examples

```
use hybrid_array::{Array, typenum::{U0, U2, U3, U5, U10}};

let a: Array<Array<usize, U3>, U2> = Array([Array([1, 2, 3]), Array([4, 5, 6])]);
assert_eq!(a.as_flattened(), &[1, 2, 3, 4, 5, 6]);

let b: Array<Array<usize, U2>, U3> = Array([Array([1, 2]), Array([3, 4]), Array([5, 6])]);
assert_eq!(a.as_flattened(), b.as_flattened());

let c: Array<[usize; 2], U3> = Array([[1, 2], [3, 4], [5, 6]]);
assert_eq!(a.as_flattened(), c.as_flattened());

let slice_of_empty_arrays: &Array<Array<i32, U5>, U0> = &Array::from_fn(|_| Array([1, 2, 3, 4, 5]));
assert!(slice_of_empty_arrays.as_flattened().is_empty());

let empty_slice_of_arrays: &Array<Array<u32, U10>, U0>  = &Array([]);
assert!(empty_slice_of_arrays.as_flattened().is_empty());
```

Associates an [`ArraySize`] with a given type. Can be used to accept `[T; N]` const generic
arguments and convert to [`Array`] internally.

This trait is also the magic glue that makes the [`ArrayN`][`crate::ArrayN`] type alias work.

# Example

```
use hybrid_array::{ArrayN, AssocArraySize};

pub fn example<const N: usize>(bytes: &[u8; N])
where
    [u8; N]: AssocArraySize + AsRef<ArrayN<u8, N>>
{
    // _arrayn is ArrayN<u8, N>
    let _arrayn = bytes.as_ref();
}
```

Takes a `&mut Array<Array<T, N>,M>`, and flattens it to a `&mut [T]`.

# Panics

This panics if the length of the resulting slice would overflow a `usize`.

This is only possible when flattening a slice of arrays of zero-sized
types, and thus tends to be irrelevant in practice. If
`size_of::<T>() > 0`, this will never panic.

# Examples

```
use hybrid_array::{Array, typenum::U3};

fn add_5_to_all(slice: &mut [i32]) {
    for i in slice {
        *i += 5;
    }
}

let mut array: Array<Array<i32, U3>, U3> = Array([Array([1_i32, 2, 3]), Array([4, 5, 6]), Array([7, 8, 9])]);
add_5_to_all(array.as_flattened_mut());
assert_eq!(array, Array([Array([6, 7, 8]), Array([9, 10, 11]), Array([12, 13, 14])]));
```

Obtain an `&Array` reference for a given type.

This provides functionality equivalent to `AsRef<Array>` or `Borrow<Array>`, but is deliberately
implemented as its own trait both so it can leverage [`AssocArraySize`] to determine the
array size, and also to avoid inference problems that occur when third party impls of traits
like [`AsRef`] and [`Borrow`] are added to `[T; N]`.

# Usage with `[T; N]`

```
use hybrid_array::{Array, ArraySize, AsArrayRef};

pub fn getn_hybrid<T, U: ArraySize>(arr: &Array<T, U>, n: usize) -> &T {
    &arr[2]
}

pub fn getn_generic<T, const N: usize>(arr: &[T; N], n: usize) -> &T
where
    [T; N]: AsArrayRef<T>
{
    getn_hybrid(arr.as_array_ref(), n)
}

let array = [0u8, 1, 2, 3];
let x = getn_generic(&array, 2);
assert_eq!(x, &2);
```

