use std::net::Ipv6Addr;
use ipnet::{IpNet, PrefixLenError};

let net = IpNet::with_netmask(Ipv6Addr::LOCALHOST.into(), Ipv6Addr::from(0xffff_ffff_ffff_0000_0000_0000_0000_0000).into());
