let max: Ipv6Addr = "ffff:ffff:ffff:ffff:ffff:ffff:ffff:ffff".parse().unwrap();

assert_eq!(ip0.saturating_add(5), ip1);
assert_eq!(ip2.saturating_add(1), max);
assert_eq!(ip2.saturating_add(5), max);
```

