use once_cell::unsync::Lazy;

let mut lazy = Lazy::new(|| 92);

assert_eq!(Lazy::get_mut(&mut lazy), None);
assert_eq!(*lazy, 92);
assert_eq!(Lazy::get_mut(&mut lazy), Some(&mut 92));
