# use std::sync::atomic::{AtomicBool, Ordering};
# use tokio::runtime;
# use tokio::sync::Barrier;
# pub fn main() {
let once = AtomicBool::new(true);
let barrier = Arc::new(Barrier::new(2));

let runtime = runtime::Builder::new_current_thread()
